using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace Mimiclay;

/// <summary>One row of the material remap table: FBX material name → project material.</summary>
public class FbxMaterialRemap
{
	[KeyProperty] public string FbxMaterial { get; set; }
	[KeyProperty] public Material Material { get; set; }
}

/// <summary>
/// Marks a GameObject as generated by an <see cref="FbxBlockoutImporter"/>, keyed by the FBX
/// object it came from so reimports update it in place (renaming the GameObject is safe).
/// </summary>
public sealed class FbxImportedPiece : Component
{
	[Property, ReadOnly] public string SourceName { get; set; }
}

/// <summary>
/// Live Blender → s&amp;box bridge for level blockouts. Point it at an .fbx inside the Assets
/// folder and it builds a child GameObject per FBX object (ModelRenderer + optional ModelCollider,
/// runtime-built model — no .vmdl compile). It polls the file and reimports the moment Blender
/// re-exports, so alt-tabbing back to s&amp;box shows the new geometry.
///
/// Children persist in the scene and are matched by FBX object name on reimport, so per-child
/// tweaks like ModelRenderer.Tint survive. Transforms always come from the FBX (move things in
/// Blender, not here). Objects deleted in Blender get their children deleted here.
/// </summary>
[Title( "FBX Blockout Importer" )]
[Category( "Level" )]
[Icon( "sync" )]
public sealed class FbxBlockoutImporter : Component, Component.ExecuteInEditor
{
	/// <summary>Path of the .fbx relative to the Assets folder, e.g. "blockout/kitchen.fbx".</summary>
	[Property] public string FbxPath { get; set; } = "";

	/// <summary>Extra multiplier on top of the FBX unit conversion (file units are treated as cm →
	/// converted to inches). At 1 a real-world Blender scene is physically correct (1m → 39.37 units);
	/// set 2.54 if you model with 1 Blender unit = 1 s&amp;box unit.</summary>
	[Property, Range( 0.01f, 100f ) ] public float ImportScale { get; set; } = 1f;

	/// <summary>Build a static ModelCollider per piece from the render geometry.</summary>
	[Property] public bool BuildCollision { get; set; } = true;

	/// <summary>Poll the file and reimport automatically when it changes.</summary>
	[Property, Group( "Auto Reimport" )] public bool AutoReimport { get; set; } = true;

	/// <summary>Seconds between file checks.</summary>
	[Property, Group( "Auto Reimport" ), Range( 0.1f, 5f )] public float CheckInterval { get; set; } = 0.5f;

	/// <summary>Used for FBX materials with no remap entry. Falls back to a dev material.</summary>
	[Property, Group( "Materials" )] public Material DefaultMaterial { get; set; }

	/// <summary>FBX material name → project material. Use "Scan FBX Materials" to fill in the names.</summary>
	[Property, Group( "Materials" )] public List<FbxMaterialRemap> MaterialRemaps { get; set; } = new();

	[Property, ReadOnly, Group( "Status" )] public string LastImport { get; set; } = "";

	ulong _importedHash;
	ulong _failedHash;
	RealTimeSince _sinceCheck;

	protected override void OnEnabled()
	{
		_importedHash = 0;
		_failedHash = 0;
		TryImport( quiet: false );
	}

	protected override void OnUpdate()
	{
		if ( !AutoReimport )
			return;
		if ( _sinceCheck < CheckInterval )
			return;

		_sinceCheck = 0;
		TryImport( quiet: true );
	}

	[Button( "Reimport Now" )]
	public void ReimportNow()
	{
		_importedHash = 0;
		_failedHash = 0;
		TryImport( quiet: false );
	}

	/// <summary>Read the FBX and add a remap row for every material it references that we don't have yet.</summary>
	[Button( "Scan FBX Materials" )]
	public void ScanMaterials()
	{
		var bytes = ReadFileBytes( out var error );
		if ( bytes == null )
		{
			Log.Warning( $"[FbxBlockout] {error}" );
			return;
		}

		try
		{
			FbxSceneReader.Read( bytes, ImportScale, out var names );
			MaterialRemaps ??= new List<FbxMaterialRemap>();
			var added = 0;
			foreach ( var name in names )
			{
				if ( MaterialRemaps.Any( r => string.Equals( r?.FbxMaterial, name, StringComparison.OrdinalIgnoreCase ) ) )
					continue;
				MaterialRemaps.Add( new FbxMaterialRemap { FbxMaterial = name } );
				added++;
			}
			Log.Info( $"[FbxBlockout] {names.Count} material(s) in file, {added} new remap row(s) added." );
		}
		catch ( Exception e )
		{
			Log.Warning( $"[FbxBlockout] Couldn't scan '{FbxPath}': {e.Message}" );
		}
	}

	// ---------------------------------------------------------------- import

	void TryImport( bool quiet )
	{
		var bytes = ReadFileBytes( out var error );
		if ( bytes == null )
		{
			if ( !quiet )
			{
				LastImport = error;
				Log.Warning( $"[FbxBlockout] {error}" );
			}
			return;
		}

		var hash = Fnv1a( bytes );
		if ( hash == _importedHash )
			return;
		if ( hash == _failedHash )
			return; // already failed on this exact content — wait for the next export

		try
		{
			var pieces = FbxSceneReader.Read( bytes, ImportScale, out _ );
			SyncChildren( pieces );
			_importedHash = hash;
			_failedHash = 0;
			var tris = pieces.Sum( p => p.SubMeshes.Sum( s => s.Vertices.Count ) ) / 3;
			LastImport = $"{pieces.Count} object(s), {tris} tris — {DateTime.Now:HH:mm:ss}";
			Log.Info( $"[FbxBlockout] Imported '{FbxPath}': {LastImport}" );
		}
		catch ( Exception e )
		{
			// mid-write reads land here too; the hash changes again once Blender finishes writing
			_failedHash = hash;
			LastImport = $"Import failed: {e.Message}";
			Log.Warning( $"[FbxBlockout] Import of '{FbxPath}' failed: {e.Message}" );
		}
	}

	void SyncChildren( List<FbxPiece> pieces )
	{
		// existing imported children by source name
		var existing = new Dictionary<string, GameObject>( StringComparer.OrdinalIgnoreCase );
		foreach ( var child in GameObject.Children )
		{
			var marker = child.Components.Get<FbxImportedPiece>( FindMode.EverythingInSelf );
			if ( marker.IsValid() && !string.IsNullOrEmpty( marker.SourceName ) )
				existing[marker.SourceName] = child;
		}

		var kept = new HashSet<string>( StringComparer.OrdinalIgnoreCase );

		foreach ( var piece in pieces )
		{
			kept.Add( piece.Name );

			if ( !existing.TryGetValue( piece.Name, out var go ) || !go.IsValid() )
			{
				go = new GameObject( true, piece.Name );
				go.Parent = GameObject;
				go.Components.Create<FbxImportedPiece>().SourceName = piece.Name;
			}

			go.LocalPosition = piece.Position;
			go.LocalRotation = piece.Rotation;
			go.LocalScale = piece.Scale;

			var model = BuildModel( piece );

			var renderer = go.Components.GetOrCreate<ModelRenderer>();
			renderer.Model = model;

			var collider = go.Components.Get<ModelCollider>( FindMode.EverythingInSelf );
			if ( BuildCollision )
			{
				collider ??= go.Components.Create<ModelCollider>();
				collider.Enabled = true;
				collider.Model = model;
			}
			else
			{
				collider?.Destroy();
			}
		}

		// remove children whose FBX object no longer exists
		foreach ( var (name, go) in existing )
		{
			if ( !kept.Contains( name ) && go.IsValid() )
				go.Destroy();
		}
	}

	Model BuildModel( FbxPiece piece )
	{
		var builder = Model.Builder;

		foreach ( var sub in piece.SubMeshes )
		{
			if ( sub.Vertices.Count == 0 )
				continue;

			var mesh = new Mesh( ResolveMaterial( sub.MaterialName ) );
			mesh.CreateVertexBuffer( sub.Vertices.Count, sub.Vertices );

			var indices = new List<int>( sub.Vertices.Count );
			for ( var i = 0; i < sub.Vertices.Count; i++ )
				indices.Add( i );
			mesh.CreateIndexBuffer( indices.Count, indices );
			mesh.Bounds = sub.Bounds;

			builder.AddMesh( mesh );
		}

		if ( BuildCollision && piece.CollisionIndices.Count > 0 )
			builder.AddCollisionMesh( piece.CollisionVertices, piece.CollisionIndices );

		return builder.Create();
	}

	Material ResolveMaterial( string fbxName )
	{
		var entry = MaterialRemaps?.FirstOrDefault( r =>
			string.Equals( r?.FbxMaterial, fbxName, StringComparison.OrdinalIgnoreCase ) );

		if ( entry?.Material != null )
			return entry.Material;
		if ( DefaultMaterial != null )
			return DefaultMaterial;

		return Material.Load( "materials/dev/reflectivity_30.vmat" );
	}

	// ---------------------------------------------------------------- file access

	byte[] ReadFileBytes( out string error )
	{
		error = null;

		if ( string.IsNullOrWhiteSpace( FbxPath ) )
		{
			error = "No FBX path set.";
			return null;
		}

		var path = FbxPath.Replace( '\\', '/' ).Trim().TrimStart( '/' );
		if ( path.StartsWith( "assets/", StringComparison.OrdinalIgnoreCase ) )
			path = path.Substring( 7 );

		try
		{
			if ( !FileSystem.Mounted.FileExists( path ) )
			{
				error = $"'{path}' not found in the mounted filesystem (path is relative to Assets).";
				return null;
			}

			using var stream = FileSystem.Mounted.OpenRead( path );
			using var ms = new MemoryStream();
			stream.CopyTo( ms );
			return ms.ToArray();
		}
		catch ( Exception e )
		{
			// Blender may still be writing — treat as transient
			error = $"Couldn't read '{path}': {e.Message}";
			return null;
		}
	}

	static ulong Fnv1a( byte[] data )
	{
		var hash = 14695981039346656037UL;
		foreach ( var b in data )
			hash = (hash ^ b) * 1099511628211UL;
		return hash;
	}
}
